// Build-time only (reads the outline files from disk). Never import from a client island.
// Files are generated by model/build_outline_data.py into src/data/real/outlines/<SITECODE>.json and are absent on a fresh checkout.
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { getCourseIndex } from './index';
import { compareSections } from '../../components/outline/outlineText';

export interface OutlineGrade { component: string; weight_pct: number | null; group: boolean | null }
export interface OutlineFinal {
  exists: boolean | null; weight_pct: number | null; duration: string | null; book: string | null;
  cheat_sheet: string | null; calculator: string | null; online: boolean | null; take_home: boolean | null;
}
export interface OutlineMidterm { exists: boolean | null; week_label: string | null; weight_pct: number | null }
export interface OutlineWeek { week_label: string; kind: string; topics: string[] }
export interface OutlineSummary {
  grading: OutlineGrade[];
  /** True when the outline gives different weights in different places (see the build's review file). */
  weights_note: boolean;
  final_exam: OutlineFinal | null;
  midterm: OutlineMidterm | null;
  weekly: OutlineWeek[];
  extra_credit: string | null;
  textbooks: string[];
}
export interface OutlineSection { section: string; classNumber: string; instructor: string; sha: string | null }
export interface OutlineDoc { pdf: string; summary: OutlineSummary | null }
export interface OutlineFile { term: string; sections: OutlineSection[]; docs: Record<string, OutlineDoc> }

const DIR = join(process.cwd(), 'src/data/real/outlines');
const cache = new Map<string, OutlineFile | null>();

/** One course's outlines with sections in natural order (G2 before G10). A section whose outline is missing from `docs` counts as having none. Null when no section has an outline. */
export function getOutline(code: string): OutlineFile | null {
  if (cache.has(code)) return cache.get(code)!;
  let out: OutlineFile | null = null;
  try {
    const raw = JSON.parse(readFileSync(join(DIR, `${code}.json`), 'utf8')) as OutlineFile;
    const sections = raw.sections
      .map((s) => ({ ...s, sha: s.sha && raw.docs[s.sha] ? s.sha : null }))
      .sort((a, b) => compareSections(a.section, b.section));
    if (sections.some((s) => s.sha)) out = { term: raw.term, sections, docs: raw.docs };
  } catch {
    out = null;
  }
  cache.set(code, out);
  return out;
}

export const hasOutline = (code: string): boolean => existsSync(join(DIR, `${code}.json`)) && getOutline(code) !== null;

/** Site codes of the courses that have an outline page. */
export function outlineCodes(): string[] {
  if (!existsSync(DIR)) return [];
  const files = new Set(readdirSync(DIR).filter((f) => f.endsWith('.json')).map((f) => f.slice(0, -5)));
  return getCourseIndex().map((c) => c.code).filter((c) => files.has(c) && getOutline(c) !== null);
}
